```c
#include <stddef.h>

size_t xstrlcpy(char *dst, const char *src, size_t dstsize) {
    size_t i = 0;
    if (dstsize != 0) {
        for (; i + 1 < dstsize && src[i]; i++)
            dst[i] = src[i];
        dst[i] = '\0';
    }
    while (src[i]) i++;
    return i;
}
```

Always NUL-terminates when `dstsize > 0`. Return value is `strlen(src)` so callers can detect truncation.
